{
  "name": "HP 437B射频功率计",
  "name_en": "HP 437B RF Power Meter",
  "manufacturer": "Hewlett-Packard (HP)",
  "description": "HP 437B是一款台式射频/微波功率计，用于配合功率传感器测量射频信号功率。它支持清零、校准、量程控制以及线性/对数单位显示，常用于射频与微波实验中测量信号源输出功率、器件插入损耗和系统功率水平。",
  "description_en": "The HP 437B is a benchtop RF/microwave power meter used with power sensors to measure RF signal power. It supports zeroing, calibration, range control, and linear/logarithmic unit display, and is commonly used in RF and microwave labs to measure source output power, insertion loss, and general power levels in test setups.",
  "tag_hints": [
    "RF power measurement",
    "microwave test",
    "benchtop power meter",
    "sensor zeroing",
    "power calibration",
    "range control",
    "linear and logarithmic units"
  ],
  "actions": [
    {
      "action_name": "auto-preset",
      "description": "将功率计恢复到已知初始状态。",
      "description_en": "Return the power meter to a known preset state."
    },
    {
      "action_name": "auto-discover",
      "description": "识别并确认已连接的功率计。",
      "description_en": "Identify and confirm the connected power meter."
    },
    {
      "action_name": "auto-measure",
      "description": "执行一次功率测量。",
      "description_en": "Perform a power measurement."
    },
    {
      "action_name": "auto-message",
      "description": "设置或读取仪器显示消息。",
      "description_en": "Set or read the instrument display message."
    },
    {
      "action_name": "auto-displayread",
      "description": "读取当前显示的测量值。",
      "description_en": "Read the currently displayed measurement value."
    },
    {
      "action_name": "auto-key",
      "description": "模拟按下面板按键。",
      "description_en": "Simulate a front-panel key press."
    },
    {
      "action_name": "auto-zero",
      "description": "执行清零操作。",
      "description_en": "Perform a zeroing operation."
    },
    {
      "action_name": "auto-calibrate",
      "description": "执行校准操作。",
      "description_en": "Perform a calibration operation."
    },
    {
      "action_name": "auto-correctionfactor",
      "description": "设置校正因子。",
      "description_en": "Set the correction factor."
    },
    {
      "action_name": "auto-statusmessage",
      "description": "读取当前状态消息或状态代码。",
      "description_en": "Read the current status message or status code."
    },
    {
      "action_name": "auto-rangeauto",
      "description": "启用自动量程。",
      "description_en": "Enable auto ranging."
    },
    {
      "action_name": "auto-rangehold",
      "description": "保持当前量程不变。",
      "description_en": "Hold the current measurement range."
    },
    {
      "action_name": "auto-rangemanual",
      "description": "设置手动量程。",
      "description_en": "Set the measurement range manually."
    },
    {
      "action_name": "auto-lin",
      "description": "切换到线性单位显示。",
      "description_en": "Switch to linear display units."
    },
    {
      "action_name": "auto-unitslog",
      "description": "切换到对数单位显示。",
      "description_en": "Switch to logarithmic display units."
    }
  ]
}

